SELECT b.branch_id, b.branch_name, dn.blood_group, u_spec.component, count(u.unit_id)::int AS available_units FROM branch b CROSS JOIN (SELECT DISTINCT blood_group FROM donor) dn CROSS JOIN (SELECT DISTINCT component FROM component_spec) u_spec LEFT JOIN donation d ON d.branch_id = b.branch_id LEFT JOIN donor dnr ON dnr.donor_id = d.donor_id AND dnr.blood_group = dn.blood_group LEFT JOIN blood_unit u ON u.donation_id = d.donation_id AND u.component = u_spec.component AND u.status = 'AVAILABLE' GROUP BY b.branch_id, b.branch_name, dn.blood_group, u_spec.component HAVING count(u.unit_id) < 5 ORDER BY available_units ASC;
